    c.cust = { n: 1 + Math.floor(this.rnd() * 3), state: 'in', wait: 0, exit: p, paid: 0 };
    const q = this.queue.length, qp = C(31.4 + (q % 2) * .8, 31.6 + Math.floor(q / 2) * .7);
