      if (Math.hypot(v[0], v[1]) > .1) { const d = game.view.screenDirToGround(v[0], v[1]), k = Math.min(1, Math.hypot(v[0], v[1])) * 150 * dt; cam.aim.x += d[0] * k; cam.aim.y += d[1] * k; }
