/* ---- 11-missions-b.js ---- */
// WIRETAP: field missions, part two. The tail (distance band, counter-surveillance, the partner hand-off), the trash
// search, the raid (plan, breach, reactions, search; the 60-second rescue), the money tail and the long lens, and Tee's
// nights on the corner (the order wheel, the code card and pager, the payphone keypad, the count).
const TEE_DRY = [[30, 32], [30, 26], [28, 26, 'window', 3], [20, 26, 'lookBack'], [9, 26], [9, 21], [15, 20.5, 'doubleBack'], [29, 20.5], [30, 15, 'wait', 4], [44, 15, 'lookBack'], [56, 15], [56, 30],
  [41, 30, 'phone', 4], [34, 30], [33, 31, 'window', 3], [30, 32], [30, 44, 'wait', 3], [18, 45], [18, 49]];
const COUNT_RUN = [[27, 36], [26, 36], [25, 41], [25, 42.5, 'cut'], [30, 43], [33, 31, 'window', 3], [33, 26], [33, 21, 'lookBack'], [46, 21]];
/** a route walker with counter-surveillance acts: the target of a tail */
function routeBrain(route, o = {}) {
  return (a, dt, F) => {
    const st = a.rt = a.rt || { i: 1, act: null, t: 0, back: 0 };
    if (st.i >= route.length) { a.stop(); a.arrived = true; return; }
    if (st.act) { st.t -= dt; a.stop();
      if (st.act === 'lookBack') { a.facing = E.approachAng(a.facing, (a.walkDir || 0) + Math.PI, dt * 6); a.fov = 2.2; }
      else if (st.act === 'window') { a.fov = 1.2; a.facing = E.approachAng(a.facing, (a.walkDir || 0) + Math.PI, dt * 3); }
      else if (st.act === 'phone') a.pose = 'phone';
      if (st.t <= 0) { st.act = null; a.fov = o.fov || 1.5; a.pose = null; }
      return; }
    const w = route[st.i], p = C(w[0], w[1]);
    if (!a.goal) a.goTo(p.x, p.y, w[2] === 'cut' ? 70 : (o.speed || 46), () => {
      const nxt = route[st.i]; st.i++;
      if (o.onWaypoint) o.onWaypoint(st.i - 1, a);
      if (nxt[2] && nxt[2] !== 'cut') { st.act = nxt[2] === 'doubleBack' ? null : nxt[2]; st.t = nxt[3] || 2.5; if (nxt[2] === 'doubleBack') { const b = C(nxt[0] - 3, nxt[1]); a.goTo(b.x, b.y, 46); } }
      if (o.extraLook && o.extraLook.includes(st.i - 1)) { st.act = 'lookBack'; st.t = 2.5; }
    });
    if (a.goal) a.walkDir = Math.atan2(a.goal.y - a.y, a.goal.x - a.x);
  };
}
function tailCheck(F, dt, tgt, o = {}) {
  const me = F.me, d = dist(me, tgt), sight = World.map.sight({ x: me.x, y: me.y, z: 0 }, { x: tgt.x, y: tgt.y, z: 0 });
  me.tooClose = d < 64; F.band = d;
  const lose = DIFF().lose * 1.5 * (o.ease || 1);
  if (d > 240 || !sight) F.losing = (F.losing || 0) + dt; else F.losing = Math.max(0, (F.losing || 0) - dt * 2);
  // mirroring: stopping when he stops
  const ra = tgt.rt && tgt.rt.act; if (ra && ra !== 'phone' && me.still > .5 && me.still < 3 && !me.cover && sight && d < 170) me.still = 2.1;
  if (F.losing > lose) return 'lost';
  return null;
}
MISSIONS.tail = {
  place: 'Penn Row, the long way', mood: 'night', rain: .6, clock: ['20:00', '21:20'], clockRate: .8, start: [30, 27], civilians: 8, stamina: true, music: 'field',
  setup(F) {
    const extra = STATE.meters.heat >= 70 ? [6, 11, 15] : [];
    const tee = F.tee = npc('tee', 30, 32, { id: 'teeT', watcher: true, range: 170, fov: 1.5 }); tee.brain = routeBrain(TEE_DRY, { extraLook: extra, onWaypoint: i => { if ([4, 9, 13].includes(i)) F.cp = i; } });
    F.cp = 0; F.extraCops = [];
    const lou = F.partner = makePlayer('lou', C(26, 27), { id: 'lou', ctl: new BotCtl() }); lou.brain = (a, dt) => this.shadow(F, a, dt);
    F.handT = 0;
    F.interact({ id: 'hand', at: () => F.me, r: 999, verb: 'Hand off to partner', when: () => false, act: () => {} });
  },
  intro: () => [['lou', "He's going to dry clean. Doubles back, stops in windows, looks behind him. When he stops, you keep walking."], ['lou', "If he looks at you twice, give me the eye. I'll be a street over."]],
  afterIntro() { tip('tail', 'The tail', 'Stay in the green band. Too close and he notices; too far or out of sight and you lose him. Press ' + Prompt.label('partner') + ' to hand the eye to your partner.'); },
  shadow(F, a, dt) {   // the AI detective: 120-200 units from the target, outside its cone, a block over if it can
    const t = F.tee; a.ctl.mv = [0, 0];
    const want = { x: t.x - Math.cos(t.walkDir || 0) * 150 + Math.sin(t.walkDir || 0) * 40, y: t.y - Math.sin(t.walkDir || 0) * 150 - Math.cos(t.walkDir || 0) * 40 }, w = nearWalk(want.x, want.y);
    const d = dist(a, w); if (d > 20) { const f = World.flow(...World.map.toCell(w.x, w.y)).next(a.x, a.y), tg = f || w, l = Math.hypot(tg.x - a.x, tg.y - a.y) || 1; a.body.vx = (tg.x - a.x) / l * (d > 120 ? 85 : 52); a.body.vy = (tg.y - a.y) / l * (d > 120 ? 85 : 52); a.facing = Math.atan2(a.body.vy, a.body.vx); a.moving = true; a.still = 0; }
    else { a.body.vx = a.body.vy = 0; a.moving = false; a.still += dt; }
    a.body.update(dt, World.map); a.rig.update(dt, { x: a.x, y: a.y, z: 0, vx: a.body.vx, vy: a.body.vy, facing: a.facing });
  },
  update(F, dt) {
    const me = F.me, lou = F.partner, t = F.tee; F.handT -= dt;
    if (!F.flags.end && t.arrived) { F.flags.end = 1; for (const [id, cx, cy] of [['tavon', 17, 50], ['rook', 19, 50.5], ['pigeon', 18.5, 48.8]]) { const a = npc(id, cx, cy, { face: Math.PI }); a.role = 'crew'; } t.say('Everybody get one. New number Monday.'); t.doAct('handout', 30, 'count'); t.role = 'lieutenant'; toast('The handout', 'Read it: watch Tee hand them out.'); }
    if (F.flags.end) { if (me.cam.watching && me.cam.target === t && me.cam.readT > 2.5 && !F.flags.read) { F.flags.read = 1; addFact('obs:tee:burners', 4, true); addEvidence({ id: 'obs:burners', kind: 'obs', text: 'Tee handing out new phones at the basketball court' }); STATE.stats.tails++; Talk.run([['lou', 'Throwaways. Everybody on that court just got a new number.'], ['dana', 'And the boxes they came in went somewhere.']], () => finish()); } return; }
    // the hand-off: the other detective takes the eye
    if (me.ctl.pressed('partner') && F.handT <= 0) {
      const om = t.minds[lou.id];
      if (dist(lou, t) < 220 && (!om || om.level < .3)) { F.handT = 20; const hc = me.ctl; me.ctl = lou.ctl; lou.ctl = hc; F.me = lou; F.partner = me; me.brain = (a, dt2) => this.shadow(F, a, dt2); lou.brain = null; sfx('radio'); toast('Hand-off', nameOf(F.me.person) + ' has the eye.'); }
      else toast('Not yet', 'Your partner can\'t pick him up from there.');
    }
    const r = tailCheck(F, dt, t);
    if (r === 'lost') this.retry(F, 'You lost him.');
  },
  onMade(F, o, q) { if (o === F.tee) { this.retry(F, 'He made you.'); meter('heat', 10, 'Tee made a tail'); return false; } },
  retry(F, why) {
    STATE.stats.retries++; meter('brass', -5, 'Retry: ' + why);
    const i = F.cp, t = F.tee, w = TEE_DRY[i], p = C(w[0], w[1]); t.body.x = p.x; t.body.y = p.y; t.rt = { i: i + 1, act: null, t: 0 }; t.stop(); Perception.reset([t], F.me.id); Perception.reset([t], F.partner.id);
    const pw = TEE_DRY[Math.max(0, i - 1)], back = C(pw[0], pw[1]); F.me.body.x = back.x; F.me.body.y = back.y; F.losing = 0; toast(why, 'Back to the last checkpoint.');
  },
  bars(F) { const d = F.band || 0, c = d < 64 ? '#ff6040' : d < 160 ? '#7ad06a' : d < 220 ? '#ffc040' : '#ff6040'; return [{ label: d < 64 ? 'Too close' : d > 160 ? 'Losing him' : 'Distance: good', value: clamp(1 - Math.abs(d - 112) / 160, 0, 1), max: 1, color: c }, ...(F.losing > 0 ? [{ label: 'Losing him', value: F.losing, max: DIFF().lose, color: '#ff6040' }] : [])]; },
  objective(F) { return F.flags.end ? { step: 'EP4 · TAIL', title: 'Read the handout', text: 'Hold the camera on Tee', at: { x: F.tee.x, y: F.tee.y } } : { step: 'EP4 · TAIL', title: 'Tail Tee', text: 'Don\'t stop when he stops', at: { x: F.tee.x, y: F.tee.y } }; },
  prompt: F => F.handT <= 0 && !F.flags.end ? { act: 'partner', label: 'Hand off', hint: nameOf(F.partner.person) } : null,
  counts: F => [['Hand-off', F.handT > 0 ? Math.ceil(F.handT) + 's' : 'ready']],
  bot(F, dt) { const me = F.me, t = F.tee, d = dist(me, t); me.ctl.mv = d > 110 ? [(t.x - me.x) / d, (t.y - me.y) / d] : [0, 0]; Perception.reset([t], me.id); if (F.t > 6 && !F.flags.bh) { F.flags.bh = 1; me.ctl.tap('partner'); } }
};

/* ---- 4.4 TRASH: the alley behind Ridley Wireless ---- */
MISSIONS.trash = {
  place: 'Alley behind Ridley Wireless', mood: 'night', rain: .6, clock: ['21:30', '22:15'], clockRate: .5, start: [35, 20.5], civilians: 0,
  setup(F) {
    F.flags.bags = [[39.2, 20.4], [40.4, 21.3], [41.6, 20.5], [42.3, 21.4], [43.4, 20.6]]; F.flags.good = Math.floor(RNG.sim() * 5); F.flags.done = [];
    const nep = F.nep = npc('man', 44.6, 21.4, { id: 'nephew', watcher: true, range: 110, fov: 1.4, face: Math.PI, seed: 902, pose: 'smoke' });
    const moe = F.moe = npc('moe', 30, 20.5, { id: 'moeB', watcher: true, range: 120, fov: 1.6 }); moe.speed = 90; F.moeT = 10;
    F.flags.bags.forEach((b, i) => F.interact({ id: 'bag' + i, at: C(b[0], b[1]), verb: 'Search the bag', hold: 2.5, r: 16, when: () => !F.flags.done.includes(i) && !F.flags.found,
      act: () => { F.flags.done.push(i); sfx('rustle'); const n = E.hears(F.nep, { x: F.me.x, y: F.me.y, z: 0, loud: 60 }, World.map); if (n > 0) F.nep.minds[F.me.id] && F.nep.minds[F.me.id].hear(n, F.me);
        if (i === F.flags.good) { F.flags.found = 1; FL().serials = true; addEvidence({ id: 'serials', kind: 'serials', text: 'Twelve phone boxes, serial numbers intact', direct: true }); addFact('serials:burners', 5, true); Talk.run([['dana', 'Twelve boxes. Serial numbers on every one.'], ['lou', "(radio) Get out of there. We'll let the phone company do the rest."]], () => finish()); }
        else toast('Nothing', ['Chicken bones.', 'Receipts and a wig.', 'A broken radio.', 'Wet cardboard.'][i % 4]); } }));
  },
  intro: () => [['lou', '(radio) Kid on the bike comes through every forty seconds. Nephew smokes at the back door. Stay low and stay dark.']],
  update(F, dt) {
    const n = F.nep; n.facing = Math.PI + Math.sin(F.t * .5) * 1.2;
    F.moeT -= dt; if (F.moeT <= 0 && !F.moe.goal) { F.moeT = 40; F.moeDir = !F.moeDir; F.moe.goCell(F.moeDir ? 48 : 30, F.moeDir ? 20.5 : 21.2, 90); }
    // dark alley cells cut exposure when crouched (handled by perception's light), the crouch helps more here
    F.me.crouchDark = F.me.crouching;
  },
  suspicionMul: .9,
  onMade(F, o, q) { if (q === F.me) { meter('heat', 5, 'Spotted in the alley'); toast('Spotted', 'Back to the alley entrance.'); F.me.body.x = 35 * T; F.me.body.y = 20.5 * T; Perception.reset(Field.observers(), F.me.id); return false; } },
  drawUnder(F, r) { F.flags.bags.forEach((b, i) => { if (!F.flags.done.includes(i)) r.shape('trashbag', b[0] * T, b[1] * T, 0, {}); }); r.prop('lamp', 44 * T, 21.7 * T, 0, { light: true, size: .7 }); },
  objective(F) { return { step: 'EP4 · TRASH', title: 'Find the phone boxes (' + F.flags.done.length + '/5 searched)', text: 'Crouch (' + Prompt.label('crouch') + ') and stay out of their cones', at: C(41, 20.8) }; },
  counts: () => []
};

/* ---- 5.3A THE RAID (and the 60-second rescue) ---- */
MISSIONS.raid = {
  place: 'The garage behind the Courts', mood: 'night', clock: ['21:00', '21:40'], clockRate: .5, start: [44, 46], civilians: 3, music: 'chase', stamina: true,
  setup(F) {
    F.flags.phase = FL().coreyExposed ? 'rescue' : 'plan'; F.flags.spots = [['Car trunk', 51.5, 49.6], ['Ceiling tile', 53.5, 49.6], ['Toolbox', 51.5, 51.5], ['False wall', 54.2, 51.5]];
    F.flags.stash = shuffle([0, 1, 2, 3], RNG.sim).slice(0, 2); F.flags.searched = [];
    if (F.flags.phase === 'rescue') { F.flags.rescueT = 60; F.me.body.x = 36 * T; F.me.body.y = 30.5 * T; F.rk = npc('rook', 27.5, 36, { face: 0 }); F.cy = npc('corey', 28, 35.5, { face: Math.PI, pose: 'kneel' }); }
    F.interact({ id: 'breach', at: () => F.flags.door === 'side' ? C(49.4, 50) : C(55.6, 50.5), verb: 'Breach', when: () => F.flags.phase === 'stack', act: () => this.breach(F) });
    F.interact({ id: 'teeP', at: () => F.tee || { x: -999, y: -999 }, verb: 'Show the paper', when: () => F.flags.phase === 'react' && F.tee && !F.flags.paper, act: () => { F.flags.paper = 1; Talk.run([['tee', 'Let me see the paper.'], ['dana', 'Signed by Halloway this afternoon. Sit down, Terrence.'], ['tee', "You ain't gonna find nothing with my name on it."]]); } });
    F.interact({ id: 'hands', at: () => F.rookG || { x: -999, y: -999 }, verb: 'Hands!', when: () => F.flags.phase === 'react' && F.rookG && !F.flags.rookDone, act: () => { F.flags.rookDone = 1; sfx('confirm'); F.rookG.pose = 'handsup'; F.rookG.say('Aight! Aight.'); } });
    F.interact({ id: 'moeC', at: () => F.moeR || { x: -999, y: -999 }, verb: 'Grab him', when: () => F.flags.phase === 'react' && F.moeR && !F.flags.flushDone, act: () => { F.flags.flushDone = 1; F.flags.flushSaved = 1; F.moeR.pose = 'cuffed'; toast('Stopped the flush', 'The package stays out of the pipes.'); } });
    F.flags.spots.forEach((s, i) => F.interact({ id: 'sp' + i, at: C(s[1], s[2]), verb: 'Search: ' + s[0], hold: 2, r: 22, when: () => F.flags.phase === 'search' && !F.flags.searched.includes(i), act: () => {
      F.flags.searched.push(i); sfx('rustle');
      if (F.flags.stash.includes(i)) { const first = !F.flags.got; F.flags.got = (F.flags.got || 0) + 1; toast(first ? 'The package' : 'The cash and the gun', first ? 'Two kilos, Harstad boxes.' : '$41,000 and a 9mm.'); addEvidence({ id: 'seize:' + i, kind: 'seizure', text: first ? 'Two kilos in Harstad Auto Parts boxes' : '$41,000 and a pistol', direct: true }); addFact('seized:raid' + i, 5, true); if (F.flags.got >= 2) this.results(F); }
      else toast('Nothing', 'Plaster dust and an old calendar.');
    } }));
  },
  intro(F) { return FL().coreyExposed ? [['lou', "(radio) Dana. Corey's not answering. Somebody saw Rook walk him into fourteen-twelve. Sixty seconds, maybe less."]] : [['navarre', "(radio) Friday, nine o'clock. The truck's in. Your call on the door."]]; },
  afterIntro(F) { if (F.flags.phase === 'plan') this.plan(F); },
  plan(F) {
    UI.cards({ kicker: 'THE RAID', title: 'Which door?', cards: [{ title: 'Front: the roll-up', body: 'Dana and Lou on the big door. Ren on the side.', k: 'front' }, { title: 'The side door', body: 'Quieter. The roll-up is open on Harlow.', k: 'side' }, { title: 'Both: split the team', body: 'Everybody covered. Slower breach.', k: 'both' }],
      pick: (i, c) => { F.flags.door = c.k === 'side' ? 'side' : 'front'; F.flags.both = c.k === 'both'; F.flags.phase = 'stack'; const p = F.flags.door === 'side' ? C(48.6, 50) : C(56.6, 50.5); F.me.body.x = p.x; F.me.body.y = p.y;
        F.dl = npc('dale', 52, 50.2, { face: 0 }); F.tee = npc('tee', 53, 51.6, { face: Math.PI, pose: 'kneel' }); F.moeR = npc('moe', 51.5, 52, { face: 0 }); if (FL().rookFree) F.rookG = npc('rook', 54, 49.4, { face: Math.PI }); Music.play('chase'); } });
  },
  breach(F) {
    sfx('doorRam'); game.shake(4); game.particles.dust(F.me.x, F.me.y, 10, 14);
    for (const [cx, cy] of F.flags.door === 'side' ? [[50, 50]] : [[55, 50], [55, 51]]) World.map.set(cx, cy, 0);
    if (F.flags.both) for (const [cx, cy] of [[50, 50], [55, 50], [55, 51]]) World.map.set(cx, cy, 0);
    F.flags.phase = 'react'; F.flags.reactT = 30; F.flags.flushT = 6; F.flags.gunT = 3;
    F.moeR.goCell(54, 52, 70); F.dl.goCell(F.flags.door === 'side' || F.flags.both ? 55 : 49, 50.5, 80); F.tee.say('Let me see the paper.');
    if (F.rookG) F.rookG.say('...');
    toast('BREACH', 'Moe is running for the toilet. Rook is reaching.');
  },
  update(F, dt) {
    const fl = F.flags;
    if (fl.phase === 'rescue') { fl.rescueT -= dt; F.pursuit = true;
      if (dist(F.me, C(28, 36)) < 30) { fl.phase = 'plan'; FL().coreyRescued = true; F.rk.goCell(25, 42, 90); F.rk.say('...'); F.cy.say('Detective. I-I-I...'); toast('Corey is alive', 'Rook went out the back.'); meter('case', 2, null); this.plan(F); }
      else if (fl.rescueT <= 0) { fl.phase = 'plan'; FL().coreyRescued = false; F.cy.visible = false; F.rk.visible = false; toast('Too late', 'Fourteen-twelve is empty.'); this.plan(F); } return; }
    if (fl.phase === 'react') {
      fl.reactT -= dt; fl.flushT -= dt; fl.gunT -= dt;
      if (fl.flushT <= 0 && !fl.flushDone) { fl.flushDone = 1; if (F.flags.both && RNG.sim() < .5) { fl.flushSaved = 1; toast('Ren got him', 'Moe on the floor by the toilet.'); } else { toast('Flushed', 'Some of it went down the pipes.'); meter('case', -3, null); } }
      if (fl.gunT <= 0 && F.rookG && !fl.rookDone) { fl.rookDone = 1; FL().rookDrew = true; F.rookG.say('...'); game.after(2, () => { F.rookG.pose = 'handsup'; toast('He dropped it', 'Two long seconds.'); }); }
      if (F.dl && dist(F.dl, C(55, 50.5)) < 10 && !fl.daleDone && !F.flags.both && F.flags.door === 'side') { fl.daleDone = 1; F.dl.visible = false; FL().daleEscaped = true; toast('The courier ran', 'Out the roll-up and gone.'); }
      if (fl.reactT <= 0 || (fl.rookDone && fl.flushDone && fl.paper)) { fl.phase = 'search'; toast('Search it', 'Two of these four hold something.'); }
    }
  },
  results(F) {
    F.flags.phase = 'done'; meter('brass', 40, 'Dope on the table'); meter('heat', 15, 'The raid');
    Talk.run([['lou', 'Major blow, they\'ll say. Watch.']], () => finish());
  },
  drawUnder(F, r) {
    r.shape('boxtruck', 57.5 * T, 49 * T, 0, { facing: -Math.PI / 2 }); if (F.flags.phase !== 'rescue') lightBar(58 * T, 45 * T);
    // the four places to search, with their clues: a car's trunk, a ladder under a loose ceiling tile, a toolbox, plaster dust at a false wall
    if (F.flags.phase === 'search' || F.flags.phase === 'react' || F.flags.phase === 'done') {
      const S = F.flags.spots;
      r.shape('sedan', (S[0][1] - .3) * T, (S[0][2] - .6) * T, 0, { facing: Math.PI / 2 });
      r.queue(S[1][1] * T, S[1][2] * T, 0, g => { const a = r.w(S[1][1] * T - 3, S[1][2] * T, 0), b = r.w(S[1][1] * T - 3, S[1][2] * T, 22), c = r.w(S[1][1] * T + 3, S[1][2] * T, 0), d = r.w(S[1][1] * T + 3, S[1][2] * T, 22); px.line(g, a[0], a[1], b[0], b[1], '#a8884a'); px.line(g, c[0], c[1], d[0], d[1], '#a8884a'); for (let k = 1; k < 6; k++) { const p0 = r.w(S[1][1] * T - 3, S[1][2] * T, k * 4), p1 = r.w(S[1][1] * T + 3, S[1][2] * T, k * 4); px.line(g, p0[0], p0[1], p1[0], p1[1], '#a8884a'); } });
      r.shape('chest', S[2][1] * T, S[2][2] * T, 0, { facing: 0, scale: .7, mats: { w: '#a82a22 metal', b: '#3a3a3a', l: '#c8c8c8' } });
      r.decal(() => r.groundDisc(S[3][1] * T, S[3][2] * T, 6, '#d8d0c0', .5));
      for (const [i, sp] of S.entries()) if (F.flags.searched.includes(i)) r.decal(() => r.groundRing(sp[1] * T, sp[2] * T, 7, '#5a5a5a', .5));
    }
  },
  objective(F) {
    const fl = F.flags;
    if (fl.phase === 'rescue') return { step: 'EP5 · RESCUE', title: 'Get to 1412 Gaither (' + Math.ceil(fl.rescueT) + 's)', text: 'Run.', at: C(28, 36) };
    if (fl.phase === 'stack') return { step: 'EP5 · RAID', title: 'Breach the door', text: 'On your go', at: fl.door === 'side' ? C(49.4, 50) : C(55.6, 50.5) };
    if (fl.phase === 'react') return { step: 'EP5 · RAID', title: !fl.flushDone ? 'Stop Moe before he flushes it' : !fl.rookDone && F.rookG ? 'Rook: make him show his hands' : 'Talk to Tee', text: Math.ceil(fl.reactT) + 's', at: !fl.flushDone && F.moeR ? { x: F.moeR.x, y: F.moeR.y } : F.rookG && !fl.rookDone ? { x: F.rookG.x, y: F.rookG.y } : F.tee ? { x: F.tee.x, y: F.tee.y } : null };
    if (fl.phase === 'search') { const left = fl.spots.map((s, i) => [s, i]).filter(([, i]) => !fl.searched.includes(i)).sort((a, b) => dist(F.me, C(a[0][1], a[0][2])) - dist(F.me, C(b[0][1], b[0][2]))); const nx = left[0] && left[0][0]; return { step: 'EP5 · RAID', title: 'Search the garage (' + (fl.got || 0) + '/2 found)', text: nx ? 'Next: ' + nx[0] + ' · plaster dust, a ladder, a trunk, a toolbox' : '', at: nx ? C(nx[1], nx[2]) : C(52.5, 50.5) }; }
    return null;
  },
  counts: () => []
};

/* ---- 5.3B THE COUNT: the money tail, Lonnie's headlights, the long lens on Mama B's back room ---- */
MISSIONS.count = {
  place: "Mama B's, Thursday", mood: 'night', clock: ['22:30', '23:30'], clockRate: .7, start: [34, 30.6], civilians: 6,
  setup(F) {
    const who = FL().pigeonTrust >= 70 ? 'pigeon' : 'tavon'; F.flags.who = who;
    const r = F.runner = npc(who, 27, 36, { id: 'runnerC', watcher: true, range: who === 'pigeon' ? 120 : 170, fov: 1.5 }); r.brain = routeBrain(COUNT_RUN, { speed: 44 });
    const car = F.lonnie = npc('lonnie', 31.5, 13.5, { id: 'lonnieCar', watcher: true, range: 120, fov: .5 }); car.visible = false; car.carD = 0;
    F.flags.phase = 'tail'; F.lens = { t: 0, win: 0, n: 0, aim: [0, 0], focus: 0, got: false };
    F.interact({ id: 'roof', at: C(50, 20.6), verb: 'Climb to the roof', when: () => F.flags.phase === 'roof', act: () => { F.flags.phase = 'lens'; F.me.locked = true; F.me.body.x = 50 * T; F.me.body.y = 18 * T; F.me.body.z = 40; tip('lens', 'The long lens', 'Easy only shows his face when the money changes hands. Hold the frame on him, wait, and shoot when he looks up.'); } });
  },
  intro: F => [['dana', FL().pigeonTrust >= 70 ? "Pigeon said he'd walk slow. Back door of Mama B's." : 'Tavon carries the bag on Thursdays. He watches his back.'], ['lou', "(radio) Lonnie's driving circles. Stay out of his headlights."]],
  update(F, dt) {
    const car = F.lonnie, loop = [[31.5, 13.5], [57.5, 13.5], [57.5, 28.5], [31.5, 28.5]]; car.carD += 45 * dt;
    { let d = car.carD % 2600, i = 0; for (; i < 4; i++) { const a = C(...loop[i]), b = C(...loop[(i + 1) % 4]), s = dist(a, b); if (d < s) { car.body.x = lerp(a.x, b.x, d / s); car.body.y = lerp(a.y, b.y, d / s); car.facing = angTo(a, b); break; } d -= s; } }
    if (F.flags.phase === 'tail') { const r = tailCheck(F, dt, F.runner, { ease: F.flags.who === 'pigeon' ? 1.6 : 1 }); if (r === 'lost') { STATE.stats.retries++; meter('brass', -5, 'Lost the bag'); const s = C(...COUNT_RUN[0]); F.runner.body.x = s.x; F.runner.body.y = s.y; F.runner.rt = null; F.losing = 0; F.me.body.x = 33 * T; F.me.body.y = 30.6 * T; toast('Lost him', 'Again, from the vacant.'); }
      if (F.runner.arrived) { F.flags.phase = 'roof'; F.runner.visible = false; toast('Mama B\'s back door', 'He knocked twice. Now the roof across the alley.'); } }
    if (F.flags.phase === 'lens') this.lensUpdate(F, dt);
  },
  lensUpdate(F, dt) {
    const L = F.lens, c = F.me.ctl, I = game.input; L.t += dt;
    // three count-handoff windows of 4 s, every 11 s; the count goes round again if you miss them all
    const ph = L.t % 11; L.win = ph > 6 && ph < 10;
    const s = c.aimStick(), m = c.screenMove(); const v = Math.hypot(s[0], s[1]) > .2 ? s : m;
    const ptr = c.pointer && c.pointer();
    if (ptr && F.lensRect) { L.aim = [clamp((ptr[0] - F.lensRect.x) / F.lensRect.w * 2 - 1, -1, 1), clamp((ptr[1] - F.lensRect.y) / F.lensRect.h * 2 - 1, -1, 1)]; }
    else { L.aim[0] = clamp(L.aim[0] + v[0] * dt * 1.2, -1, 1); L.aim[1] = clamp(L.aim[1] + v[1] * dt * 1.2, -1, 1); }
    if (FD.attract) { L.aim[0] = lerp(L.aim[0], -.25, dt * 3); L.aim[1] = lerp(L.aim[1], -.1, dt * 3); }
    const on = Math.hypot(L.aim[0] + .25, L.aim[1] + .1) < .18; L.focus = on ? Math.min(1, L.focus + dt * 2.5) : Math.max(0, L.focus - dt * 3);
    if (c.pressed('photo') || (FD.attract && L.win && L.focus >= 1)) {
      F.me.cam.film--; shutterSound(); const stars = (on ? 1 : 0) * ((L.win ? 1 : 0) + (L.focus >= 1 ? 1 : 0) + (L.win && on ? 1 : 0));
      const ph = { id: 'easy' + Math.floor(L.t * 10), subject: 'easy', stars, tags: stars >= 3 ? ['face', 'focus', 'act', 'act:count-handoff'] : [], turn: 0, mood: 'night', clock: fmtTime(F.clock), ep: 5 };
      STATE.photos.push(ph); Camera.render(ph, null); toast('Darnell Booker ' + '★'.repeat(stars), stars >= 3 ? 'The money in his hands. His face.' : L.win ? 'Not sharp enough' : 'He isn\'t looking up');
      if (stars >= 3 && !L.got) { L.got = true; addFact('face:easy', 2, true); addEvidence({ id: 'act:easy:count', kind: 'photo', ref: ph.id, text: 'Darnell Booker taking the count at Mama B\'s', who: 'easy', direct: true }); meter('case', 20, 'Easy in the act'); Music.sting('photoGood'); game.after(1.5, () => Talk.run([['dana', 'Got him.'], ['lou', '(radio) Then get down off that roof before Lonnie comes round again.']], () => finish())); }
    }
  },
  overlay(F, r) {
    if (F.flags.phase !== 'lens') return;
    r.overlay(g => {
      const W = r.W, H = r.H, w = Math.min(W - 40, 300), hh = Math.min(H - 70, 180), x = Math.round((W - w) / 2), y = Math.round((H - hh) / 2) - 10, L = F.lens;
      F.lensRect = { x, y, w, h: hh };
      px.rect(g, 0, 0, W, H, '#050506'); px.rect(g, x, y, w, hh, '#3a2a1e');
      px.rect(g, x, y + hh * .62, w, hh * .38, '#5a3a22'); px.rect(g, x + w * .6, y + 8, w * .3, hh * .45, '#2a1a12');   // a back room: table, a door
      px.rect(g, x + w * .18, y + hh * .55, w * .46, 8, '#6a4a2a');
      px.disc(g, Math.round(x + w * .4), y + 14, 6, '#ffe0a0');
      for (let i = 0; i < 6; i++) px.rect(g, Math.round(x + w * .28 + i * 9), Math.round(y + hh * .55 - 4 - (i % 2) * 2), 7, 4, '#6aa04a');
      const ex = Math.round(x + w * .375), ey = Math.round(y + hh * .45);   // Easy, head down unless the money moves
      rigOf('lonnie').drawPortrait(g, Math.round(x + w * .62), Math.round(y + hh * .25), 56, { zoom: 1.1, turn: .5, bg: '#3a2a1e' });
      rigOf('easy').drawPortrait(g, ex - 32, ey - 32, 64, { zoom: 1.2, turn: L.win ? 0 : .95, bg: '#3a2a1e' });
      const ax = Math.round(x + w / 2 + L.aim[0] * w / 2), ay = Math.round(y + hh / 2 + L.aim[1] * hh / 2), rad = Math.round(20 - L.focus * 10), col = L.focus >= 1 ? '#7aff8a' : '#ffd84a';
      for (const [a, b] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) { px.line(g, ax + a * rad, ay + b * rad, ax + a * (rad - 6), ay + b * rad, col); px.line(g, ax + a * rad, ay + b * rad, ax + a * rad, ay + b * (rad - 6), col); }
      E.font.text(g, L.win ? 'THE MONEY IS MOVING' : 'WAIT FOR IT', W / 2, y + hh + 8, L.win ? '#ff7a5a' : '#cfc8b8', { align: 'center', outline: false });
      Glyph.prompt(g, 'photo', 'Take photo', Math.round(W / 2) - 40, y + hh + 22, '#ffffff');
      E.font.text(g, 'FILM ' + F.me.cam.film, x, y - 12, '#ffd84a', { outline: false });
    });
  },
  objective(F) { const ph = F.flags.phase; return ph === 'tail' ? { step: 'EP5 · THE COUNT', title: 'Follow the bag', text: F.flags.who === 'pigeon' ? 'Pigeon walks slow for you' : 'Tavon checks his back', at: { x: F.runner.x, y: F.runner.y } } : ph === 'roof' ? { step: 'EP5 · THE COUNT', title: 'The vacant across the alley', text: 'Its alley door', at: C(50, 20.6) } : ph === 'lens' ? { step: 'EP5 · THE COUNT', title: 'Easy, in the act', text: 'Three stars or nothing' } : null; },
  bars: F => F.flags.phase === 'tail' ? MISSIONS.tail.bars(F) : [],
  counts: F => [['Film', F.me.cam.film]],
  bot(F, dt) { if (F.flags.phase !== 'lens') { F.flags.phase = 'lens'; F.me.locked = true; } }
};

/* ---- 12-cipher.js ---- */
// WIRETAP: the crew's pager code, "turn the pad" (App. C). The police decoder (a keypad you turn a quarter at a time,
// decoded digits updating live, a MATCH when it lands on a number you know), Tee's code card and pager, the payphone keypad.
const PAD = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9']];
const CW = { 0: 0, 1: 7, 2: 4, 3: 1, 4: 8, 5: 5, 6: 2, 7: 9, 8: 6, 9: 3 };
const inv = m => Object.fromEntries(Object.entries(m).map(([k, v]) => [v, +k]));
const CCW = inv(CW);
/** encode with the turn ('cw' = Ep1-3, 'ccw' = after the flip); decode is the other turn's map */
const encode = (num, dir = 'cw') => num.replace(/\d/g, d => (dir === 'cw' ? CW : CCW)[d]);
const decodeTurns = (num, turns) => { let s = num; const n = ((turns % 4) + 4) % 4; for (let i = 0; i < n; i++) s = s.replace(/\d/g, d => CCW[d]); return s; };   // each clockwise turn of the pad undoes one CW encoding
const CODES = { 11: 'package ready', 22: 'call me at the usual phone', 33: 'the count', 44: 'need product', 55: 'all clear', 77: 'police around', 99: 'stop everything' };
const SENDERS = { '07': 'Tee', 13: 'Rook', 14: 'Pigeon', 21: 'Corey', '00': "Easy's people" };
const PAGES_COREY = ['555-0781 22 07', '555-0743 11 00', '555-0769 33 07', '555-0769 77 14', '555-0798 44 07'];
const knownNumbers = () => Object.entries(STATE.numbers).filter(([k, v]) => v.known || k === 'H1' && hasFact('plate:harstad')).map(([k, v]) => ({ id: k, n: v.n }));
const NUM_NAME = { P1: 'Gaither Market payphone', P2: 'Suds City payphone', P3: 'bus stop payphone', H1: 'Harstad Auto Parts, Dundalk', MB: "Mama B's Soul Food", PG: 'the stash pager' };
const Cipher = {
  /** try a page against the known numbers with a number of turns; returns the match id or null */
  match(page, turns) { const cb = page.split(' ')[0], d = decodeTurns(cb, turns); const k = knownNumbers().find(x => x.n === d); return k ? k.id : null; },
  /** solve a page in evidence: Case +3 and a fact */
  solve(page, id) {
    if (STATE.cipher.decoded.includes(page)) return false; STATE.cipher.decoded.push(page);
    const [cb, code, from] = page.split(' ');
    addEvidence({ id: 'page:' + page, kind: 'page', text: 'Page ' + page + ' → ' + STATE.numbers[id].n + ' (' + NUM_NAME[id] + '): ' + (CODES[code] || '?') + ', from ' + (SENDERS[from] || from), num: id, code, from, direct: true });
    addFact('page:' + id + ':' + code, 3, true); addFact('num:' + id + ':' + (SENDERS[from] || '').toLowerCase().split(' ')[0], 0, true);
    if (from === '07') STATE.numbers[id].user = STATE.numbers[id].user || 'tee';
    BUS.emit('decoded', page, id); return true;
  },
  /** the decoder screen: pages on the right, the keypad on the left, turned with L1/R1 (Q/E) or the arrows */
  open(pages, o = {}) {
    let sel = 0, turns = 0, hint = false;
    const s = UI.open({ id: 'cipher', cls: 'cipher', legend: () => [['tabPrev', 'Turn left'], ['tabNext', 'Turn right'], ['confirm', 'Select page'], ['uiInfo', 'Hint'], ['cancel', 'Close']],
      tab: d => { turns = (turns + d + 4) % 4; sfx('pin'); check(); UI.refresh(s); }, info: () => { hint = !hint; UI.refresh(s); }, cancel: () => { UI.close(); if (o.done) o.done(); },
      render(el) {
        const pg = pages[sel] || '', cb = pg.split(' ')[0] || '', dec = decodeTurns(cb, turns), m = pg && Cipher.match(pg, turns), solved = STATE.cipher.decoded.includes(pg);
        const rot = n => { const g = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9']]; let r = g; for (let i = 0; i < n; i++) r = r[0].map((_, c) => r.map(row => row[c]).reverse()); return r; };
        const pad = rot(turns);
        el.append(h('div.panel.wire', h('div.kicker', { text: 'PAGER CODE · TURN THE PAD' }), h('div.cipher-row',
          h('div.keypad', h('button.turn', { 'data-f': '', on: () => { turns = (turns + 3) % 4; sfx('pin'); check(); UI.refresh(s, 0); } }, '⟲'), h('div.pad', { style: { transform: 'rotate(' + turns * 90 + 'deg)' } }, pad.flat().map(d => h('span.key', { text: d })).concat([h('span.key', { text: '*' }), h('span.key', { text: '0' }), h('span.key', { text: '#' })])), h('button.turn', { 'data-f': '', on: () => { turns = (turns + 1) % 4; sfx('pin'); check(); UI.refresh(s, 1); } }, '⟳'), h('div.turns', { text: turns + ' quarter turn' + (turns === 1 ? '' : 's') + ' clockwise' })),
          h('div.pages', pages.map((p, i) => h('button.page' + (i === sel ? '.sel' : '') + (STATE.cipher.decoded.includes(p) ? '.done' : ''), { 'data-f': '', on: () => { sel = i; check(); UI.refresh(s, 2 + i); } }, p)),
            h('div.decode', h('div.big', { text: pg ? dec + ' ' + pg.split(' ').slice(1).join(' ') : '' }), h('div.' + (m ? 'match' : 'nomatch'), { text: m ? 'MATCH: ' + NUM_NAME[m] + (solved ? ' ✓' : '') : 'NO MATCH' }),
              pg ? h('div.small', { text: 'Code ' + pg.split(' ')[1] + ': ' + (hasFact('stmt:corey:code') || STATE.ep >= 3 ? (CODES[pg.split(' ')[1]] || '?') : '?') + ' · from ' + pg.split(' ')[2] }) : null,
              hint ? h('div.hint', { text: STATE.cipher.flipSeen ? 'Hal: "They didn\'t change the lock. They just turned the key the other way."' : 'Corey: "It\'s the phone, man. You turn it."' }) : null)))));
      },
      model(ss) { ss.confirm = () => {}; }
    });
    function check() { const pg = pages[sel], m = pg && Cipher.match(pg, turns); if (m && Cipher.solve(pg, m)) { toast('Decoded', pg + ' → ' + NUM_NAME[m]); Music.sting('photoGood'); if (o.onSolve) o.onSolve(pg, m); } else if (pg && !m && STATE.cipher.decoded.length && turns === 1 && !Cipher.match(pg, 1)) { STATE.cipher.noMatch = (STATE.cipher.noMatch || 0) + 1; } }
    return s;
  },
  /** Tee's side: the pager and the code card (plaintext and encoded side by side) */
  teeCard(o = {}) {
    const dir = STATE.cipher.dir;
    const s = UI.open({ id: 'codecard', cls: 'cipher', legend: [['confirm', 'Send'], ['cancel', 'Close']], cancel: () => { UI.close(); },
      render(el) {
        el.append(h('div.panel.wire', h('div.kicker', { text: "TEE'S PAGER · THE CODE CARD" }),
          h('div.cipher-row', h('div.card-code', h('h3', { text: 'Turn the pad ' + (dir === 'cw' ? 'right' : 'left') }), h('div.map', Object.keys(CW).map(d => h('span', { text: d + '→' + (dir === 'cw' ? CW : CCW)[d] })))),
            h('div.pages', h('div.small', { text: 'Incoming' }), ...(o.inbox || []).map(p => h('div.page', { text: p })),
              h('div.small', { text: 'Page the re-up: call me back at…' }),
              ...['P1', 'P2', 'P3'].map(id => { const n = STATE.numbers[id].n, enc = encode(n, dir) + ' 44 07'; return btn(id + '  ' + n + '  →  ' + enc, () => { UI.close(); if (o.send) o.send(id, enc); }); })))));
      },
      model(ss) { ss.confirm = () => { UI.close(ss); if (o.send) o.send('P1', encode(STATE.numbers.P1.n, dir) + ' 44 07'); }; }
    });
    return s;
  },
  /** a payphone's keypad: dial digits with real DTMF tones; done(number) */
  dial(target, done) {
    let typed = '';
    const press = d => { typed += d; sfx('dtmf' + d); if (typed.replace(/-/g, '').length >= 7) { const num = typed.slice(0, 3) + '-' + typed.slice(3, 7); game.after(.4, () => { UI.close(s); done(num); }); } UI.refresh(s); };
    const s = UI.open({ id: 'dial', cls: 'dial', legend: [['confirm', 'Press'], ['cancel', 'Hang up']], cancel: () => { UI.close(); done(null); },
      render(el) {
        el.append(h('div.panel.dark', h('div.kicker', { text: 'PAYPHONE · 25¢' }), h('div.big', { text: (typed.length > 3 ? typed.slice(0, 3) + '-' + typed.slice(3) : typed) || '___-____' }),
          target ? h('div.small', { text: 'The card says: ' + target }) : null,
          h('div.dialpad', ['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'].map(d => btn(d, () => { if (/\d/.test(d)) press(d); }, 'dkey')))));
      },
      model(ss) { ss.confirm = () => { for (const d of (target || '5550174').replace(/\D/g, '')) press(d); }; }
    });
    return s;
  }
};

/* ---- 13-tee.js ---- */
// WIRETAP: playing Tee. One night shift on the corner (the CornerSim with Tee as its lieutenant): the order wheel (hold
// Partner), studying people to call out a cop, the pager and the code card, the payphone keypad, the patrol, the knockers,
// the count at the end against Easy's number.
const INTERLUDES = {
  i1: { title: 'Interlude 1 · Night shift', target: 450, secs: 210, events: [[20, 'dutch'], [45, 'patrol'], [10, 'pigeonSleep'], [70, 'ud'], [130, 'reupNeed']],
    intro: [['rook', 'Who told you the old man\'s name, Tee? The bus driver.'], ['tee', 'Nobody told me nothing. Somebody called 911 and somebody downtown read it out loud. That\'s how it works.'], ['rook', 'Then it works for us.'], ['tee', 'It works till it don\'t. Count\'s at two. Get on your spot.']] },
  i2: { title: 'Interlude 2 · New stash', target: 420, secs: 180, events: [[5, 'stashPick'], [40, 'reupNeed'], [90, 'knockers'], [60, 'ud']],
    intro: [['tee', 'Corey\'s in Central. That means the stash moves tonight. And the phones... we pick a phone they ain\'t sitting on.']] },
  i3: { title: 'Interlude 3 · Making it back', target: 560, secs: 210, events: [[50, 'hearse'], [100, 'ud'], [120, 'shots']],
    intro: [['tee', 'Double shift. Pigeon running. We make back what Sunday took or Easy takes it out of somebody.']] },
  i4: { title: 'Interlude 4 · Throwaways', target: 380, secs: 150, events: [[25, 'danaCar'], [60, 'ud']],
    intro: [['tee', 'Everybody got the new phones? Old ones in the harbor. Not the trash. The harbor.']] }
};
const WHEEL = [['Shut it down', 'shut'], ['Open up', 'open'], ['Move the stash', 'stash'], ['Post up here', 'post']];
MISSIONS.tee = {
  place: 'Gaither & Ridley, night', mood: 'night', clock: ['22:00', '02:00'], clockRate: 1, player: 'tee', start: [30.2, 31.2], civilians: 8, music: 'corner',
  corner: { rate: .35, patrol: true, autoReup: false, vials: 60 },
  setup(F, data) {
    const I = F.il = INTERLUDES[data.il || 'i1']; F.flags.il = data.il || 'i1'; F.flags.T = 0; F.flags.ev = I.events.map(e => ({ t: e[0], k: e[1], done: false }));
    F.flags.inbox = STATE.cipher.dir === 'ccw' ? ['555-0312 11 00'] : ['555-0798 11 00']; F.clockRate = 240 / I.secs;
    const c = F.corner; c.o.payphones = false; c.led.start = c.led.vials;
    if (data.il === 'i2') { c.agents = c.agents.filter(a => a.person !== 'corey'); c.crew.stash = null; }
    if (data.il === 'i3' && !FL().rookFree) { c.agents = c.agents.filter(a => a.person !== 'rook'); c.crew.muscle = null; }
    // payphones: Tee dials the re-up on the number from the card
    for (const id of ['P1', 'P2', 'P3']) F.interact({ id: 'pay' + id, at: C(POI[id][0], POI[id][1] + (POI[id][1] === 26 ? .4 : -.4)), verb: 'Use the payphone', hint: id, when: () => F.flags.needCall, act: () => Cipher.dial('555-0174', n => {
      if (n === '555-0174') { F.flags.needCall = false; F.flags.called = id; FL().payphone = FL().payphone || id; sfx('ringback'); toast('Re-up ordered', 'The package comes in about forty seconds.'); c.reupT = 40; c.o.autoReup = false; game.after(40, () => { c.reup(100); toast('Package in', '100 vials'); }); }
      else if (n) toast('Wrong number', 'A woman yelling about her cable.'); }) });
    F.interact({ id: 'wake', at: C(34.3, 37.2), verb: 'Wake up, Pigeon', when: () => F.flags.asleep, act: () => { F.flags.asleep = false; const pg = c.agents.find(a => a.person === 'pigeon'); if (pg) { pg.watcher = true; pg.say('I\'m up! I\'m up.'); } } });
    F.interact({ id: 'dutch', at: () => F.dutch || { x: -999, y: -999 }, verb: 'Deal with Dutch', when: () => F.dutch && !F.flags.dutchDone, act: () => Talk.run([['man', 'Tee. Tee. I got eight. I\'m two short, I swear on my mother, I got you Friday.'],
      { choices: ['Let it slide', 'Turn him away', 'Let Rook handle it'], pick: i => { F.flags.dutchDone = 1; FL().dutch = ['slide', 'away', 'rook'][i]; if (i === 0) { c.led.vials -= 1; c.led.sold += 1; return [['tee', 'Friday. And Dutch? Everybody hears about it if you don\'t.']]; } if (i === 2) { meter('heat', 5, null); return [['rook', 'Come here, Dutch.'], ['tee', '...Easy, Rook. Easy.']]; } return [['tee', 'Ten is ten. Go on.']]; } }], () => { if (F.dutch) c.leave(F.dutch); }) });
    tip('tee', 'Tee', 'You run the corner tonight. Hold ' + Prompt.label('partner') + ' for orders. Hold ' + Prompt.label('watch') + ' to study people; ' + Prompt.label('photo') + ' calls out a cop. ' + Prompt.label('notebook') + ' opens your pager.');
  },
  intro: (F) => F.il.intro,
  pager(F) { Cipher.teeCard({ inbox: F.flags.inbox, send: (id, enc) => { F.flags.needCall = true; F.flags.paged = id; pagerSound(); toast('Paged', enc + ' · now call it in from a payphone'); } }); },
  update(F, dt) {
    const fl = F.flags, c = F.corner, me = F.me; fl.T += dt;
    for (const e of fl.ev) if (!e.done && fl.T >= e.t) { e.done = true; this.event(F, e.k); }
    // the order wheel: hold Partner, point, let go
    if (me.ctl.down('partner')) { F.wheel = F.wheel || { t: 0, sel: -1 }; F.wheel.t += dt; const m = me.ctl.screenMove(), ptr = me.ctl.pointer && me.ctl.pointer();
      let v = Math.hypot(m[0], m[1]) > .4 ? m : null; if (ptr && me.scr) { const dx = ptr[0] - me.scr[0], dy = ptr[1] - me.scr[1]; if (Math.hypot(dx, dy) > 12) v = [dx, dy]; }
      if (v) { const a = Math.atan2(v[1], v[0]); F.wheel.sel = Math.round(((a + Math.PI / 2 + TAU) % TAU) / (TAU / 4)) % 4; } me.locked = true; }
    else if (F.wheel) { const s = F.wheel.sel; F.wheel = null; me.locked = false; if (s >= 0) this.order(F, WHEEL[s][1]); }
    // calling out a cop: study someone, then Photo
    if (me.cam.watching && me.ctl.pressed('photo') && me.cam.target) { const t = me.cam.target; if (t.undercover) { t.burnedOut = true; t.say('...'); t.goCell(1, 26.5, 60, () => { t.gone = true; }); toast('Called out', 'Plainclothes. He\'s walking.'); meter('heat', 3, null); fl.callouts = (fl.callouts || 0) + 1; c.shutdown('callout', 15); }
      else if (t.cust || (!t.role && !t.person)) { toast('Wrong', 'Just a man waiting on the bus. The line backs off.'); c.spawnT = 10; } }
    if (F.ud && !F.ud.gone) this.udBrain(F, dt);
    if (fl.T >= F.il.secs && !fl.counted) { fl.counted = true; this.count(F); }
  },
  order(F, k) {
    const c = F.corner, me = F.me;
    if (k === 'shut') { c.shutdown('tee', 20); me.say('Shut it down.'); }
    else if (k === 'open') { c.openUp(); }
    else if (k === 'stash') { const n = { v1412: 'buick', buick: 'trashGate', trashGate: 'v1412' }[c.o.stash]; c.setStash(n); FL().stashSpot = n; toast('Stash moved', { v1412: 'Back in 1412', buick: 'Wheel well of the dead Buick', trashGate: 'Trash can by the court' }[n]); }
    else if (k === 'post') { const l = (c.crew.lookouts || []).find(a => a.z < 1); if (l) { l.home = { x: me.x, y: me.y }; l.goTo(me.x, me.y, 70); l.say('Aight.'); } }
    sfx('confirm');
  },
  event(F, k) {
    const c = F.corner;
    if (k === 'dutch') { F.dutch = c.customers[0] || null; if (!F.dutch) { c.spawnCustomer(); F.dutch = c.customers[c.customers.length - 1]; } F.dutch.say('Tee! Tee, lemme talk to you.'); }
    if (k === 'patrol') { c.patrol = { d: 0, wait: 0, on: true, x: PATROL_LOOP[0][0], y: PATROL_LOOP[0][1], f: 0 }; toast('Patrol', 'A radio car on Abbott. Shut it down before it turns onto Ridley.'); }
    if (k === 'pigeonSleep') { const pg = c.agents.find(a => a.person === 'pigeon'); if (pg) { pg.watcher = false; pg.say('zzz'); F.flags.asleep = true; toast('Pigeon\'s asleep', 'On the roof. Wake him from the stoop.'); } }
    if (k === 'reupNeed') { toast('Running low', 'Page the re-up from your pager (' + Prompt.label('notebook') + '), then call it in.'); c.led.vials = Math.min(c.led.vials, 25); c.led.start = c.led.start; }
    if (k === 'knockers') { const tgt = c.crew.runner || c.agents[0]; c.knockers(tgt); toast('Knockers!', 'Jump-out boys on the runner.'); }
    if (k === 'hearse') { toast('A hearse', 'Black, slow, down Ridley. Everybody freezes.'); c.shutdown('hearse', 25); sfx('engine'); }
    if (k === 'shots' && !FL().wallOff) { sfx('gunshot'); game.after(.4, () => sfx('gunshot')); game.shake(2); c.shutdown('shots', 40); toast('Shots on Harlow', 'Two. Far off. Rook went after the hearse.'); FL().rookAfterSunday = true; }
    if (k === 'danaCar') { Talk.run([['tee', 'Beige Lumina. Same one from Tuesday. That\'s her.'], ['tavon', 'Who?'], ['tee', 'Ridley girl. Police now. Smile at her.']]); }
    if (k === 'stashPick') UI.cards({ kicker: 'THE STASH', title: 'Corey\'s gone. Where does it live now?', cards: [{ title: 'The dead Buick', body: 'Close. Quick. Anybody can look in a wheel well.', k: 'buick' }, { title: 'Trash can by the court', body: 'Far. Safe. Slow.', k: 'trashGate' }, { title: 'Back in 1412', body: 'Behind the radiator. Slow and safe.', k: 'v1412' }],
      pick: (i, cd) => { F.corner.setStash(cd.k); FL().stashSpot = cd.k; } });
    if (k === 'ud') { const s = C(20, 30.6), a = F.ud = new Agent({ id: 'ud', x: s.x, y: s.y, seed: 4242, speed: 40 }); a.undercover = true; a.cop = true; F.civs.push(a); }
  },
  udBrain(F, dt) { const a = F.ud; a.udT = (a.udT || 0) - dt; if (a.udT <= 0 && !a.goal) { a.udT = 6; const v = VANTAGE[Math.floor(RNG.sim() * 6)]; a.goCell(v[0], v[1], 40, () => { a.doAct('camera', .8, 'camera'); a.facing = angTo(a, F.corner.crew.money || F.me); }); } },
  count(F) {
    const c = F.corner, total = c.led.banked + c.led.cash, tgt = F.il.target; FL().teeShort = FL().teeShort || total < tgt; STATE.crew.count = total;
    let shown = 0;
    const s = UI.open({ id: 'count', cls: 'count', legend: [['confirm', 'Continue']], tick: (dt) => { if (shown < total) { shown = Math.min(total, shown + Math.max(10, total * dt / 2.5)); sfx('cashflick'); UI.refresh(s); } },
      render(el) { el.append(h('div.panel.dark', h('div.kicker', { text: 'THE COUNT' }), h('div.huge', { text: '$' + Math.round(shown).toLocaleString() }), h('div.small', { text: 'Easy\'s number: $' + tgt.toLocaleString() }),
        h('div.bar', h('i', { style: { width: Math.min(100, shown / tgt * 100) + '%' } })), shown >= total ? h('p.lede', { text: total >= tgt ? 'Short of nothing. Lonnie counts it twice and nods.' : 'Short. Lonnie writes a number on a napkin and folds it.' }) : null, btn('Continue', () => { UI.close(); MISSIONS.tee.endChoice(F); }))); },
      model(ss) { ss.confirm = () => { UI.close(ss); MISSIONS.tee.endChoice(F); }; } });
  },
  endChoice(F) {
    const il = F.flags.il, end = r => finish(r);
    if (il === 'i1') return Talk.run([['tee', FL().dutch === 'rook' ? 'Rook. Next time I say easy, it means easy.' : 'Tomorrow we do it again.']], () => end());
    if (il === 'i2') return UI.cards({ kicker: 'COREY', title: 'Corey\'s in Central Booking', cards: [{ title: 'Bail him out', body: 'He comes home owing.' }, { title: 'Let him sit', body: 'Nobody visits.' }, { title: '"Rook wants to send a message"', body: 'Let Rook decide.', cost: 'Corey in danger' }], pick: i => { FL().coreyFate = ['bail', 'sit', 'message'][i]; end(); } });
    if (il === 'i3') return UI.cards({ kicker: 'THE LOSS', title: 'Who takes the loss to Easy?', cards: [{ title: 'Tee', body: 'It was my corner.' }, { title: 'Corey', body: 'He talked. Everybody knows he talked.' }, { title: 'Pigeon', body: 'He was on the roof. He missed the hearse.' }], pick: i => { FL().lossOn = ['tee', 'corey', 'pigeon'][i]; end(); } });
    if (il === 'i4') return UI.cards({ kicker: 'A CANARY', title: 'Feed Corey a fake re-up time?', text: 'If it comes back to you through the police, you know who\'s talking.', cards: [{ title: 'Yes', body: 'Tell Corey Saturday. It\'s Friday.' }, { title: 'No', body: 'Leave it.' }], pick: i => { FL().canary = i === 0; if (FL().canary && FL().coreyCI) FL().coreyExposed = true; end(); } });
    end();
  },
  overlay(F, r) {
    if (!F.wheel || F.wheel.t < .15) return;
    r.overlay(g => { const s = F.me.scr || [r.W / 2, r.H / 2], cx = Math.round(s[0]), cy = Math.round(s[1]);
      px.blend(g, .6, 'normal', () => px.disc(g, cx, cy, 46, '#0a0a0a'));
      WHEEL.forEach(([lab], i) => { const a = -Math.PI / 2 + i * TAU / 4, x = cx + Math.cos(a) * 34, y = cy + Math.sin(a) * 30, on = F.wheel.sel === i;
        E.font.text(g, lab, Math.round(x), Math.round(y) - 3, on ? '#ffb347' : '#e8e4dc', { align: 'center', shadow: '#000', outline: false }); if (on) px.line(g, cx, cy, Math.round(x), Math.round(y), '#ffb347'); }); });
  },
  objective(F) { const c = F.corner, tot = c.led.banked + c.led.cash, left = Math.max(0, F.il.secs - F.flags.T);
    if (F.flags.asleep) return { step: F.il.title, title: 'Pigeon\'s asleep on the roof', text: 'Wake him from Miss Odessa\'s stoop', at: C(34.3, 37.2) };
    if (F.flags.needCall) return { step: F.il.title, title: 'Call the re-up in', text: 'Any payphone. Dial what the card says.', at: C(...POI[F.flags.paged || 'P1']) };
    return { step: F.il.title, title: 'Make the count: $' + tot + ' / $' + F.il.target, text: Math.floor(left / 60) + ':' + String(Math.floor(left % 60)).padStart(2, '0') + ' left · ' + (c.open ? 'open' : 'shut down') }; },
  counts: F => [['Vials', F.corner.led.vials], ['Count', '$' + (F.corner.led.banked + F.corner.led.cash)]],
  prompt: F => ({ act: 'partner', label: 'Orders (hold)' }),
  bot(F, dt) { const c = F.corner; if (c.patrol && c.patrol.on && c.open) MISSIONS.tee.order(F, 'shut'); F.me.ctl.mv = [0, 0]; }
};

/* ---- 14-case.js ---- */
// WIRETAP: the case. The Board (cards, slots by tier, strings, validation by facts), the Notebook (objectives, map,
// people, evidence, phones, the case), the box (four approaches on a face-button diamond; the kitchen variant), and the
// paper: the affidavit (probable cause, necessity honesty) and Judge Halloway's three questions.
const portraitURL = (() => { const c = {}; return id => { if (!HAS_DOM || !CAST[id]) return ''; if (c[id]) return c[id]; try { const cv = document.createElement('canvas'); cv.width = cv.height = 48; const g = cv.getContext('2d'); px.rect(g, 0, 0, 48, 48, '#3a342c'); rigOf(id).drawPortrait(g, 0, 0, 48, { zoom: 1, bg: '#3a342c' }); return (c[id] = cv.toDataURL()); } catch (e) { return ''; } }; })();
const photoOf = id => { const p = STATE.photos.slice().reverse().find(q => q.subject === id && q.tags.includes('face')); return p ? Camera.render(p, null) || PHOTO_IMG[p.id] : null; };
const knowsPerson = id => hasFact('face:' + id) || hasFact('name:' + id) || hasFact('voice:' + id);

/* ---- THE BOARD ---- */
const TIERS = [
  { id: 'corner', name: 'THE CORNER', slots: [['lieutenant', 'Lieutenant', 'tee'], ['muscle', 'Muscle', 'rook'], ['stash', 'Stash', 'corey'], ['money', 'Money', 'dink'], ['runner', 'Runner', 'tavon'], ['lookout', 'Lookout', 'pigeon'], ['lookout2', 'Lookout', 'moe']] },
  { id: 'package', name: 'THE PACKAGE', slots: [['courier', 'Courier', 'dale'], ['supplier', 'Supplier front', 'harstad'], ['reup', 'Re-up spot', 'gas']] },
  { id: 'money', name: 'THE MONEY', slots: [['boss', 'Boss', 'easy'], ['driver', 'Driver', 'lonnie'], ['front', 'Front', 'mamab']] }
];
const BIZ = { harstad: { name: 'Harstad Auto Parts', need: 'plate:harstad' }, gas: { name: 'Arundel Gas (closed)', need: 'reup:gas' }, mamab: { name: "Mama B's Soul Food", need: 'int:mamab' }, garage: { name: 'Garage behind the Courts', need: 'int:garage' } };
const Board = {
  /** what a slot needs, and why not */
  canPin(slot, card) {
    const [sid, , who] = slot;
    if (card !== who && !(sid === 'lookout' && card === 'moe' && who === 'pigeon') && !(sid === 'lookout2' && card === 'pigeon')) return 'Says who? Nothing puts ' + (CAST[card] ? nameOf(card) : BIZ[card] ? BIZ[card].name : card) + ' in that chair.';
    if (BIZ[card]) return hasFact(BIZ[card].need) ? null : 'Get me something that ties it in.';
    const role = { lieutenant: 'lieutenant', muscle: 'muscle', stash: 'stash', money: 'money', runner: 'runner', lookout: 'lookout', lookout2: 'lookout' }[sid];
    if (role && !(hasFact('obs:' + card + ':' + role) || STATE.facts.some(f => f.startsWith('stmt:') && f.includes(card)) || (card === 'tee' && hasFact('stmt:corey:tee-lieutenant')) || (card === 'corey' && hasFact('seized:pager')))) return 'You\'ve got a face. Now show me him doing the job.';
    if (sid === 'courier' && !(hasFact('act:dale:reup-handoff') || hasFact('face:dale'))) return 'Who says he\'s more than a delivery man?';
    if (sid === 'boss' && !(hasFact('int:boss') || hasFact('face:easy'))) return 'A name on a wire is a rumor. Keep listening.';
    if (sid === 'driver' && !hasFact('voice:lonnie') && !hasFact('int:mamab')) return 'Get his voice first.';
    return null;
  },
  pin(slot, card) {
    const why = this.canPin(slot, card); if (why) { toast('Szabo', why); sfx('cancel'); return false; }
    if (STATE.board.pins[slot[0]] === card) return true;
    STATE.board.pins[slot[0]] = card; sfx('pin'); meter('case', 2, 'Pinned: ' + slot[1]); BUS.emit('pin', slot[0], card); return true;
  },
  canLink(a, b) { const ph = ['P1', 'P2', 'P3', 'PG'].includes(a) ? a : b, who = ph === a ? b : a; if (!CAST[who]) return false;
    return STATE.numbers[ph] && (STATE.numbers[ph].user === who || hasFact('num:' + ph + ':' + who) || STATE.evidence.some(e => e.who === who && e.act === 'payphone' && ph === 'P1') || (ph === 'PG' && who === 'corey')); },
  link(a, b) { if (!this.canLink(a, b)) { toast('Szabo', 'A string needs a reason. Who\'s on that phone?'); sfx('cancel'); return false; }
    if (STATE.board.links.some(l => (l[0] === a && l[1] === b) || (l[0] === b && l[1] === a))) return true; STATE.board.links.push([a, b]); sfx('string'); meter('case', 1, 'String: ' + nameOf(CAST[a] ? a : b) + ' ↔ ' + (CAST[a] ? b : a)); return true; },
  cards() {
    const people = Object.keys(CAST).filter(id => ['tee', 'rook', 'corey', 'dink', 'tavon', 'pigeon', 'moe', 'dale', 'easy', 'lonnie', 'sunday'].includes(id) && knowsPerson(id));
    const phones = ['P1', 'P2', 'P3', 'PG'].filter(k => STATE.numbers[k].known);
    const biz = Object.keys(BIZ).filter(k => hasFact(BIZ[k].need));
    return { people, phones, biz };
  },
  open(o = {}) {
    let tier = 0, sel = null;
    const s = UI.open({ id: 'board', cls: 'board', legend: [['confirm', 'Pick / pin'], ['tabPrev', 'Tier'], ['tabNext', 'Tier'], ['uiAlt', 'Unpin'], ['cancel', 'Close']],
      tab: d => { tier = (tier + d + TIERS.length) % TIERS.length; UI.refresh(s, 0); }, cancel: () => { UI.close(); if (o.done) o.done(); },
      alt: () => { const b = s.items[s.fi]; if (b && b.dataset.slot && STATE.board.pins[b.dataset.slot]) { delete STATE.board.pins[b.dataset.slot]; sfx('cancel'); UI.refresh(s); } },
      render(el) {
        const T = TIERS[tier], cs = Board.cards();
        const card = (id, kind) => h('button.bcard' + (sel === id ? '.sel' : ''), { 'data-f': '', on: () => { if (sel && sel !== id && (kind === 'phone' || ['P1', 'P2', 'P3', 'PG'].includes(sel))) { Board.link(sel, id); sel = null; } else sel = sel === id ? null : id; UI.refresh(s); } },
          kind === 'person' ? h('img', { src: photoOf(id) || portraitURL(id), alt: '' }) : h('div.bicon', { text: kind === 'phone' ? '☎' : '■' }),
          h('span', { text: kind === 'person' ? nameOf(id) : kind === 'phone' ? id + ' ' + STATE.numbers[id].n : BIZ[id].name }));
        el.append(h('div.panel.cork', h('div.tierbar', TIERS.map((t, i) => h('span' + (i === tier ? '.on' : ''), { text: t.name }))),
          h('div.slots', T.slots.map(sl => { const pin = STATE.board.pins[sl[0]]; return h('button.slot' + (pin ? '.pinned' : ''), { 'data-f': '', 'data-slot': sl[0], on: () => { if (sel) { if (Board.pin(sl, sel)) sel = null; UI.refresh(s); } else if (pin) toast(sl[1], nameOf(pin)); } },
            h('div.slot-t', { text: sl[1] }), pin ? h('img', { src: CAST[pin] ? photoOf(pin) || portraitURL(pin) : '', alt: '' }) : h('div.q', { text: '?' }), h('div.slot-n', { text: pin ? (CAST[pin] ? CAST[pin].name : BIZ[pin].name) : '' })); })),
          h('div.cardrow', ...cs.people.slice(0, 8).map(id => card(id, 'person')), ...cs.phones.map(id => card(id, 'phone')), ...(tier ? cs.biz.map(id => card(id, 'biz')) : [])),
          h('div.strings', { text: STATE.board.links.map(l => nameOf(CAST[l[0]] ? l[0] : l[1]) + ' — ' + (CAST[l[0]] ? l[1] : l[0])).join('   ·   ') || (sel ? 'Pick a slot, or a phone to tie a string' : 'Pick a card') })));
      },
      model(ss) { ss.confirm = () => { for (const t of TIERS) for (const sl of t.slots) if (!Board.canPin(sl, sl[2])) Board.pin(sl, sl[2]); UI.close(ss); if (o.done) o.done(); }; }
    });
    tip('board', 'The Board', 'Pick a face, then the chair it sits in. A pin needs a fact behind it. Pick a person and a phone to tie a string.');
    return s;
  }
};

/* ---- THE NOTEBOOK ---- */
const Notebook = {
  tabs: ['objectives', 'map', 'people', 'evidence', 'phones', 'case'],
  open(tab = 'objectives') {
    let ti = Math.max(0, this.tabs.indexOf(tab)), page = 0;
    const s = UI.open({ id: 'notebook', cls: 'notebook', legend: [['tabPrev', 'Tab'], ['tabNext', 'Tab'], ['cancel', 'Close']], tab: d => { ti = (ti + d + 6) % 6; page = 0; UI.refresh(s, 0); }, cancel: () => UI.close(),
      render(el) {
        const t = Notebook.tabs[ti], body = h('div.nb-body.scroll');
        if (t === 'objectives') { const o = Director.objectiveText(); body.append(h('h2', { text: o.title }), h('p.lede', { text: o.text }), ...(o.list || []).map(l => h('p', { text: '• ' + l }))); }
        if (t === 'map') { const cv = h('canvas', { width: 216, height: 168 }); body.append(cv); const g = cv.getContext('2d'); const M = World.map;
          for (let y = 0; y < 56; y++) for (let x = 0; x < 72; x++) { const ch = ROWS[y][x]; g.fillStyle = WT[ch] ? '#5a4a3c' : ch === '=' ? '#2a2a2e' : ch === '-' ? '#3a3834' : ch === 'f' || ch === 'x' ? '#6a6a50' : '#8a8a80'; g.fillRect(x * 3, y * 3, 3, 3); }
          const mk = (cx, cy, c, l) => { g.fillStyle = c; g.fillRect(cx * 3 - 2, cy * 3 - 2, 5, 5); body.append(h('div.mk', { text: l, style: { color: c } })); };
          for (const id of ['P1', 'P2', 'P3']) if (STATE.numbers[id].known) mk(POI[id][0], POI[id][1], '#7aa7ff', id + ' payphone');
          mk(30, 32, '#ff5a4a', 'The corner'); mk(46, 26, '#ffb347', "Mama B's"); if (FL().dreLine) mk(63, 48, '#45d6a0', 'Arundel Gas (where Dre broke his ankle)');
          if (FD.me && game.sceneName === 'field') mk(FD.me.x / T, FD.me.y / T, '#ffffff', 'You'); }
        if (t === 'people') { const ids = ['tee', 'rook', 'corey', 'dink', 'tavon', 'pigeon', 'moe', 'dale', 'easy', 'lonnie', 'sunday', 'pockets', 'odessa'].filter(knowsPerson);
          body.append(h('div.grid', (ids.length ? ids : []).map(id => h('div.person', h('img', { src: photoOf(id) || portraitURL(id), alt: '' }), h('b', { text: CAST[id].name }), h('span', { text: (STATE.facts.find(f => f.startsWith('obs:' + id + ':')) || '').split(':')[2] || 'role unknown' })))));
          if (!ids.length) body.append(h('p', { text: 'Nobody yet. Faces first.' })); }
        if (t === 'evidence') { const ev = STATE.evidence.slice(-12); body.append(h('div.grid', ev.map(e => h('div.ev', e.ref && PHOTO_IMG[e.ref] ? h('img', { src: PHOTO_IMG[e.ref], alt: '' }) : h('div.bicon', { text: { page: '#', stmt: '"', seizure: '■', obs: '•', int: '☎', plate: '▭', serials: '▤' }[e.kind] || '•' }), h('span', { text: e.text })))));
          if (!ev.length) body.append(h('p', { text: 'Nothing in the locker.' })); }
        if (t === 'phones') { for (const [k, v] of Object.entries(STATE.numbers)) if (v.known) body.append(h('p', { text: k + '  ' + v.n + '  ' + (NUM_NAME[k] || '') + (v.user ? ' · used by ' + nameOf(v.user) : '') + (v.dead ? ' · DEAD' : '') }));
          for (const p of STATE.cipher.decoded) body.append(h('p.mono', { text: 'Page ' + p })); }
        if (t === 'case') { const m = STATE.meters, heat = m.heat < 30 ? 'Calm' : m.heat < 50 ? 'Wary' : m.heat < 75 ? 'Spooked' : 'Gone dark';
          body.append(...[['Case', m.case, 160], ["Major's patience", m.brass, 100], ['Legal risk', m.legal, 100]].map(([l, v, mx]) => h('div.meter', h('b', { text: l + '  ' + v }), h('div.bar', h('i', { style: { width: Math.min(100, v / mx * 100) + '%' } })))),
            h('p', { text: 'Street: ' + heat + ' (' + m.heat + ')' }), h('p', { text: 'Photos ' + STATE.stats.photos + ' · made ' + STATE.stats.made + ' times · minimized ' + STATE.stats.minimized + ' · violations ' + STATE.stats.violations }), h('p', { text: 'Fund $' + m.fund })); }
        el.append(h('div.panel.manila', h('div.tabs', Notebook.tabs.map((x, i) => h('span' + (i === ti ? '.on' : ''), { text: x.toUpperCase() }))), body, btn('Close', () => UI.close())));
      } });
  }
};

/* ---- THE BOX ---- */
const BOX = {
  corey: { who: 'corey', resolve: 100, fear: 30, n: 12, kind: 'box',
    beats: [{ id: 'B1', need: s => s.resolve <= 75, say: 'Tee. Terrence. He run Gaither. I just... I just sit.', fact: 'stmt:corey:tee-lieutenant' },
      { id: 'B2', need: s => s.resolve <= 50 && s.shown.includes('pager'), say: "The numbers... it's the phone, man. You turn it. That's all I know.", fact: 'stmt:corey:code' },
      { id: 'B3', need: s => s.resolve <= 25, say: "Fourteen-twelve. Behind the radiator. There's a board loose.", fact: 'stmt:corey:stash' }],
    ev: { package: [-30, 0, ['dana', 'Forty vials. Orange tops. Your prints on the bag.'], ['corey', 'That bag was on the ground.']], pager: [-15, 0, ['lou', "Your pager's been busy, Corey. Real popular kid."], ['corey', 'Everybody got a pager.']],
      'act:corey:stash-access': [-25, 0, ['dana', "That's you going into fourteen-twelve. Again. And again."], ['corey', '...']], 'face:corey': [-10, 0, ['dana', "That's you."], ['corey', 'That could be anybody.']], 'face:tee': [-10, 0, ['dana', 'Who is this?'], ['corey', "I don't know him."]] },
    lines: { lean: [['lou', "You know what distribution in a school zone gets you? That court's a school zone, Corey. Look it up."], ["I ain't distributing nothing. I was sitting.", "Why y'all on me? I'm nobody.", 'Stop. Just... stop.']],
      offer: [['dana', "You're nineteen. Tee's twenty-four. Who do you think takes the weight?"], ['Tee look out for me.', "...Tee ain't gonna let me go down.", 'What happens to me? If I say something. What happens?']],
      bluffOk: [['dana', 'Pigeon told us you hold for them.'], "Pigeon don't know nothing about— ...man."], bluffBad: [['dana', 'Rook says you set up Felton.'], "Rook don't talk to police. You making stuff up now."],
      combo: ['lou', 'Lou slams the table and walks out.'], comboD: ['dana', "He's gone. It's just me. Talk to me, Corey."], lawyer: 'I-I want a lawyer. I know my rights. I want a lawyer.', flip: "If Tee finds out, I'm dead. You know that, right? ...What I gotta do?" } },
  rook: { who: 'rook', resolve: 100, fear: 0, n: 3, kind: 'box', comic: [['dana', 'Nice car.', 'Lawyer.'], ['lou', "Taillight's out.", 'Lawyer.'], ['dana', "Who's the hammer for, Ricky?", 'Law. Yer.']] },
  pigeon: { who: 'pigeon', trust: 20, fear: 40, n: 8, kind: 'kitchen' }
};
const Box = {
  open(id, done) {
    const cfg = BOX[id], s = { resolve: cfg.resolve, fear: cfg.fear, trust: cfg.trust + (id === 'pigeon' && FL().odessaRespect ? 15 : 0), rapport: 0, n: cfg.n, shown: [], got: [], last: null, pushes: 0, over: false };
    const finishBox = (why) => { if (s.over) return; s.over = true; UI.close(); Talk.run(why ? [why] : [], () => done(s)); };
    if (cfg.comic) { let i = 0; const nx = () => { if (i >= cfg.comic.length) return done(s); const [w, l, r] = cfg.comic[i++]; Talk.run([[w, l], ['rook', r]], nx); }; return nx(); }
    const say = (seq, after) => { UI.close(); Talk.run(seq, () => { after && after(); if (!s.over) this.screen(id, cfg, s, say, finishBox, done); }); };
    this.screen(id, cfg, s, say, finishBox, done);
  },
  band: s => s.resolve > 60 ? 0 : s.resolve >= 30 ? 1 : 2,
  checkBeats(cfg, s, out) {
    for (const b of cfg.beats || []) if (!s.got.includes(b.id) && b.need(s)) { s.got.push(b.id); out.push([cfg.who, b.say]); addFact(b.fact, 2, true); addEvidence({ id: b.fact, kind: 'stmt', text: nameOf(cfg.who) + ': "' + b.say + '"' }); if (b.fact === 'stmt:corey:code') STATE.cipher.hint = true; }
  },
  act(id, cfg, s, k, say, finishBox) {
    const out = []; s.n--;
    if (cfg.kind === 'kitchen') return this.kitchen(cfg, s, k, say, finishBox);
    const L = cfg.lines, b = this.band(s);
    if (k === 'lean') { s.resolve -= 12; s.fear += Math.max(5, 15 - s.rapport * 3); out.push(L.lean[0], [cfg.who, L.lean[1][b]]); }
    if (k === 'offer') { if (s.got.includes('B3') && s.fear <= 60 && s.rapport >= 1) { FL().coreyCI = true; out.push(['dana', 'Work for us.'], [cfg.who, L.flip]); addFact('ci:corey', 3, true); this.checkBeats(cfg, s, out); return say(out, () => finishBox(['lou', 'Welcome to the team, kid. Don\'t tell anybody.'])); }
      s.fear -= 15; s.resolve -= 8; out.push(L.offer[0], [cfg.who, L.offer[1][b]]); if (s.last === 'lean') { s.resolve -= 20; s.rapport = Math.min(3, s.rapport + 1); out.unshift(L.combo, L.comboD); toast('Good cop, bad cop', 'Rapport +1'); } }
    if (k === 'bluff') { if (Board.cards().people.length >= 3 && hasFact('obs:pigeon:lookout')) { s.resolve -= 25; out.push(L.bluffOk[0], [cfg.who, L.bluffOk[1]]); } else { s.resolve += 20; s.rapport = Math.max(0, s.rapport - 1); out.push(L.bluffBad[0], [cfg.who, L.bluffBad[1]]); } }
    s.last = k; s.resolve = clamp(s.resolve, 0, 100); s.fear = clamp(s.fear, 0, 100);
    this.checkBeats(cfg, s, out);
    if (s.fear >= 80) return say(out, () => finishBox([cfg.who, L.lawyer]));
    if (s.n <= 0) return say(out, () => finishBox(['lou', "Booking wants him at Central. That's all we get."]));
    say(out);
  },
  showEvidence(id, cfg, s, say, finishBox) {
    const ev = STATE.evidence.filter(e => ['photo', 'seizure', 'stmt', 'page'].includes(e.kind)).slice(-6);
    UI.open({ id: 'pick', cls: 'pick', legend: [['confirm', 'Show'], ['cancel', 'Back']], cancel: () => UI.close(),
      render(el) { el.append(h('div.panel.manila', h('div.kicker', { text: 'SHOW EVIDENCE' }), h('div.grid', ev.map(e => h('button.ev', { 'data-f': '', on: () => { UI.close(); Box.useEv(id, cfg, s, e, say, finishBox); } }, e.ref && PHOTO_IMG[e.ref] ? h('img', { src: PHOTO_IMG[e.ref], alt: '' }) : h('div.bicon', { text: '■' }), h('span', { text: e.text })))), ev.length ? null : h('p', { text: 'Nothing to show.' }), btn('Back', () => UI.close()))); },
      model(ss) { ss.confirm = () => { UI.close(ss); if (ev[0]) Box.useEv(id, cfg, s, ev[0], say, finishBox); }; } });
  },
  useEv(id, cfg, s, e, say, finishBox) {
    s.n--; const key = cfg.ev && (cfg.ev[e.id] ? e.id : e.id === 'package' ? 'package' : e.id === 'pager' ? 'pager' : null), r = key ? cfg.ev[key] : null;
    const out = [];
    if (cfg.kind === 'kitchen') { const ok = !!e; s.trust += ok ? 10 : 0; out.push(['dana', 'I know what this is. So do you.'], ['pigeon', ok ? '...Yeah.' : 'That ain\'t nothing.']); return say(out); }
    if (r) { s.resolve += r[0]; s.shown.push(key); out.push(r[2], r[3]); } else { s.resolve += 10; s.fear += 5; out.push(['dana', 'Look at this.'], [cfg.who, "That's a picture of a corner, Detective."]); }
    s.resolve = clamp(s.resolve, 0, 100); this.checkBeats(cfg, s, out); if (s.n <= 0) return say(out, () => finishBox(['lou', "Booking wants him at Central. That's all we get."])); say(out);
  },
  kitchen(cfg, s, k, say, finishBox) {
    const out = [];
    if (k === 'honest') { const ok = hasFact('obs:pigeon:lookout') || hasFact('face:pigeon'); s.trust += ok ? 15 : -5; out.push(['dana', ok ? 'I know you watch from the roof. I know Tee pays you forty a day.' : 'I know more than you think.'], ['pigeon', ok ? '...Thirty-five.' : 'You don\'t know nothing.']); }
    if (k === 'promise') { s.trust += 20; FL().promise = true; out.push(['dana', 'Nobody will know you talked to me.'], ['pigeon', 'Everybody always know.']); }
    if (k === 'push') { s.fear += 20; s.trust -= 10; s.pushes++; out.push(['dana', 'You want to end up like Corey?'], ['pigeon', '...']); if (s.pushes >= 2) return say(out, () => finishBox(['odessa', "That's enough. You can go now, Dana Lynn."])); }
    if (k === 'listen') { s.trust += 8; out.push(['pigeon', "Homers always come back. You take 'em fifty miles and they come back. That's the thing about 'em."], ['odessa', '(from the stove) Mm-hm.']); }
    if (k === 'heard') { s.trust -= 40; out.push(['dana', 'I heard your call. To your grandmother.'], ['pigeon', 'You was listening to me?']); s.usedHeard = true; }
    s.trust = clamp(s.trust, 0, 100); FL().pigeonTrust = s.trust;
    if (s.trust >= 70) { FL().pigeonTrust = Math.max(75, s.trust); addFact('stmt:pigeon:count', 3, true); addEvidence({ id: 'stmt:pigeon:count', kind: 'stmt', text: 'Pigeon: Thursdays he carries the bag to Mama B\'s back door' }); return say(out, () => finishBox(['pigeon', "Thursdays I carry the bag. Mama B's. The back door."])); }
    if (s.n <= 0) return say(out, () => finishBox(['odessa', "He's a good boy. He's fourteen. Those two things don't last long around here."]));
    say(out);
  },
  screen(id, cfg, s, say, finishBox, done) {
    const kit = cfg.kind === 'kitchen';
    const opts = kit ? [['boxTop', 'Be honest', 'honest'], ['boxLeft', 'Promise', 'promise'], ['boxRight', 'Push', 'push'], ['boxBottom', 'Listen', 'listen']]
      : [['boxTop', 'Show evidence', 'show'], ['boxLeft', 'Bluff', 'bluff'], ['boxRight', 'Lean on him', 'lean'], ['boxBottom', s.got.includes('B3') && s.fear <= 60 && s.rapport >= 1 ? 'Work for us' : 'Offer a way out', 'offer']];
    const go = k => { if (k === 'show') return this.showEvidence(id, cfg, s, say, finishBox); this.act(id, cfg, s, k, say, finishBox); };
    const keys = {}; for (const [a, , k] of opts) keys[a] = () => go(k);
    UI.open({ id: 'box', cls: 'box', keys, legend: [['confirm', 'Choose']],
      render(el) {
        const bars = kit ? [['Trust', s.trust, 100, s.trust >= 70 ? 'enough' : 'not yet'], ['Fear', s.fear, 100, s.fear > 60 ? 'scared' : 'wary']] : [['Resolve', s.resolve, 100, s.resolve > 60 ? 'holding' : s.resolve >= 30 ? 'cracking' : 'breaking'], ['Fear', s.fear, 100, s.fear >= 80 ? 'lawyer' : s.fear > 60 ? 'scared' : 'calm']];
        el.append(h('div.panel.dark.boxpanel', h('div.kicker', { text: kit ? "MISS ODESSA'S KITCHEN" : 'THE BOX · ' + CAST[cfg.who].name }),
          ...bars.map(([l, v, mx, w]) => h('div.meter', h('b', { text: l + ' · ' + w }), h('div.bar', h('i', { style: { width: v / mx * 100 + '%' } })))),
          h('div.small', { text: (kit ? '' : 'Rapport ' + '●'.repeat(s.rapport) + '○'.repeat(3 - s.rapport) + ' · ') + (kit ? 'Time ' : 'Booking wants him in ') + s.n + ' exchanges' + (s.got.length ? ' · Beats: ' + s.got.join(' ') : '') }),
          h('div.diamond', opts.map(([a, lab, k]) => h('button.dopt.' + a, { 'data-f': '', on: () => go(k), html: glyphHTML(a) + '<span>' + esc(lab) + '</span>' }))),
          kit && FL().heardPigeon && !s.usedHeard ? btn('"I heard your call."', () => go('heard'), 'special') : null));
      },
      model(ss) { ss.confirm = () => go(kit ? 'listen' : (s.last === 'lean' ? 'offer' : 'lean')); } });
  }
};

/* ---- THE PAPER: the affidavit and the judge ---- */
const NECESSITY = [['surv', 'Physical surveillance', () => STATE.stats.photos > 0], ['ci', 'Confidential informant', () => FL().pocketsMet], ['uc', 'Undercover purchase', () => false], ['sw', 'Search warrant', () => false], ['gj', 'Grand jury subpoena', () => false]];
const Paper = {
  lines() { return [{ id: 'P1', name: 'P1 · Gaither Market payphone' }, { id: 'P2', name: 'P2 · Suds City payphone' }, { id: 'PG', name: 'Pager clone · 555-0110' }, ...(STATE.numbers.P3.known ? [{ id: 'P3', name: 'P3 · bus stop payphone' }] : [])]; },
  /** probable-cause points of one evidence item for a line, and whether it is direct */
  pts(e, line) {
    if (e.kind === 'page' && e.num === line) return [2, true];
    if (line === 'PG' && e.id === 'pager') return [2, true];
    if (line === 'PG' && e.kind === 'page') return [1, true];
    if (e.kind === 'photo' && e.act === 'payphone' && line === 'P1') return [2, true];
    if (e.kind === 'photo' && e.act === 'stash-access' && line === 'PG') return [1, false];
    if (e.kind === 'stmt' && (e.id === 'stmt:corey:code' && line === 'PG')) return [1, false];
    if (e.kind === 'stmt' && e.id === 'stmt:pockets') return [1, false];
    if (e.kind === 'stmt' && e.id === 'stmt:pat' && line === 'P1') return [2, false];
    if (e.kind === 'obs' && e.id === 'numplate:' + line) return [1, false];
    if (e.kind === 'photo' && e.id.startsWith('face:') && ['tee', 'corey'].includes(e.who)) return [1, false];
    if (e.kind === 'seizure' && line === 'PG') return [1, false];
    return [0, false];
  },
  score(line, picks) { let p = 0, direct = false; for (const e of picks) { const [n, d] = this.pts(e, line); p += n; direct = direct || (d && n > 0); } return { p, direct, ok: p >= 4 && direct }; },
  open(done) {
    const lines = this.lines(), pick = Object.fromEntries(lines.map(l => [l.id, []])), nec = {}; let li = 0;
    const s = UI.open({ id: 'affidavit', cls: 'affidavit', legend: [['confirm', 'Select'], ['tabPrev', 'Line'], ['tabNext', 'Line'], ['cancel', 'Back']], tab: d => { li = (li + d + lines.length + 1) % (lines.length + 1); UI.refresh(s, 0); sfx('typekey'); },
      cancel: () => {},
      render(el) {
        const ln = lines[li], body = h('div.scroll.doc');
        if (ln) { const sc = Paper.score(ln.id, pick[ln.id]);
          body.append(h('h2', { text: 'Target line: ' + ln.name }), h('p.mono', { text: 'Probable cause: ' + sc.p + ' / 4 · ' + (sc.direct ? 'direct evidence ✓' : 'needs a direct item (an act photo or a decoded page)') }),
            h('div.grid', STATE.evidence.filter(e => Paper.pts(e, ln.id)[0] > 0 || pick[ln.id].includes(e)).slice(0, 8).map(e => { const on = pick[ln.id].includes(e), [n] = Paper.pts(e, ln.id);
              return h('button.ev' + (on ? '.sel' : ''), { 'data-f': '', on: () => { const a = pick[ln.id]; if (on) a.splice(a.indexOf(e), 1); else if (a.length < 3) a.push(e); sfx('typekey'); UI.refresh(s); } }, h('span', { text: (on ? '☑ ' : '☐ ') + e.text + '  (+' + n + ')' })); })));
        } else {
          body.append(h('h2', { text: 'Necessity: techniques tried and failed' }), h('p.small', { text: 'Tick only what you did. The judge reads every line.' }),
            ...NECESSITY.map(([k, lab]) => h('button.check' + (nec[k] ? '.on' : ''), { 'data-f': '', on: () => { nec[k] = !nec[k]; sfx('typekey'); UI.refresh(s); } }, (nec[k] ? '☑ ' : '☐ ') + lab)),
            btn('Sign and send it to Judge Halloway', () => { UI.close(); done(lines.map(l => Object.assign({}, l, Paper.score(l.id, pick[l.id]), { picks: pick[l.id] })), nec); }, 'primary'));
        }
        el.append(h('div.panel.paper', h('div.tabs', [...lines.map(l => l.id), 'NECESSITY'].map((x, i) => h('span' + (i === li ? '.on' : ''), { text: x }))), body));
      },
      model(ss) { ss.confirm = () => { for (const l of lines) { pick[l.id] = STATE.evidence.filter(e => Paper.pts(e, l.id)[0] > 0).sort((a, b) => Paper.pts(b, l.id)[0] - Paper.pts(a, l.id)[0]).slice(0, 3); } nec.surv = true; UI.close(ss); done(lines.map(l => Object.assign({}, l, Paper.score(l.id, pick[l.id]), { picks: pick[l.id] })), nec); }; } });
    tip('paper', 'The affidavit', 'Each line needs 4 points of probable cause, with at least one direct item. Then the necessity section: what you tried. Don\'t lie to a judge.');
  },
  /** Halloway's three questions: weakest lines first, any false necessity tick always */
  judge(result, nec, done) {
    const qs = [], lies = NECESSITY.filter(([k, , t]) => nec[k] && !t());
    for (const [k] of lies) qs.push({ q: k === 'uc' ? 'Tell me about the undercover buys.' : k === 'sw' ? 'Tell me about the search warrant you served.' : k === 'gj' ? "Which grand jury? I'd like to see those returns." : 'Tell me about your informant.', lie: true, answers: ['We... the paperwork is coming.', 'It was an informal arrangement.', 'I misspoke, Your Honor.'] });
    const weak = result.slice().sort((a, b) => a.p - b.p);
    for (const l of weak) { if (qs.length >= 3) break;
      if (l.id === 'PG') qs.push({ line: l, q: "These are numbers on a pager. How do you know they're phone numbers at all?", answers: [hasFact('stmt:corey:code') && STATE.cipher.decoded.length ? ['Decoded with the crew\'s keypad code, they match payphones on Ridley. A crew member described the code in an interview.', true] : ["It's how they do it.", false], ["It's how they do it.", false], ['Our informant says so.', false]] });
      else qs.push({ line: l, q: 'How do you know the man on ' + l.id + ' is the man in your photograph?', answers: [l.picks.some(e => e.kind === 'photo' && e.act === 'payphone') || l.picks.some(e => e.kind === 'page') ? ['We have him on that phone, and his pages call it back. It\'s in the exhibits.', true] : ['He\'s on that corner every day.', false], ['Our informant says so.', false], ['He\'s on that corner every day.', false]] });
    }
    while (qs.length < 3) qs.push({ q: "Who's monitoring, and do they know the rules?", answers: [['Detective Pettiford. Every call logged, minimized in the first seconds if it isn\'t pertinent.', true], ['We all take turns.', false]] });
    let i = 0, caught = false; const struck = new Set(result.filter(l => !l.ok).map(l => l.id));
    const ask = () => {
      if (i >= qs.length || caught) return end();
      const q = qs[i++], ans = q.lie ? q.answers.map(a => [a, false]) : shuffle(q.answers.slice(0, 3).filter((a, j, arr) => arr.findIndex(b => b[0] === a[0]) === j), RNG.cos);
      Talk.run([['halloway', q.q], { who: 'dana', choices: ans.map(a => a[0]), pick: j => { if (q.lie) { caught = true; FL().perjury = true; return [['halloway', "Detective, I've signed wiretaps for twenty-two years, and I regret eleven of them. This one I won't sign."]]; } if (!ans[j][1] && q.line) { struck.add(q.line.id); return [['halloway', "That's not an answer. I'm striking " + q.line.id + '.']]; } return [['halloway', 'Mm.']]; } }], ask);
    };
    const end = () => {
      const up = result.filter(l => !struck.has(l.id) && !caught);
      if (caught) { meter('brass', -15, 'Perjury in chambers'); meter('legal', 30, 'A false affidavit'); }
      if (!up.length) { if (!caught) meter('brass', -10, 'Affidavit denied'); FL().denied++; Talk.run([['vance', caught ? 'You lied to Abner Halloway. Do you know how long it took me to get him to trust this office?' : "He wants more. One more act on a payphone. Then we go back."]], () => done(false)); return; }
      for (const l of up) { STATE.wire.lines[l.id] = 'up'; }
      FL().wireUp = true; sfx('stamp'); game.shake(1);
      Talk.run([['halloway', "You're up. Thirty days. Minimize, Detective. I read the logs."], ['halloway', "If I find a grandmother's phone call in your transcripts, I'll pull this wire myself."]], () => done(up.map(l => l.id)));
    };
    Talk.run([['halloway', 'Sit, Detective. Ms. Vance, you may stay. I have three questions and a crossword.']], ask);
  }
};

/* ---- 15-wire.js ---- */
// WIRETAP: the wire room. A shift is calls on a clock (App. D). You may listen to the first seconds of every call; a
// call that isn't pertinent must be minimized (spot-check it every ten seconds), key lines must be logged as they're said,
// voices matched to people, pages decoded. Listening where the law says you can't costs Legal; at 100 the judge pulls it.
